const raw = $input.first().json || {};
const card_id = Number(raw.card_id);
if (!card_id || isNaN(card_id)) {
  throw new Error('card_id requerido. Envía un número entre 55705, 55707, 55773, 63163, 65209, 66727 o 66793. Recibido: ' + JSON.stringify(raw));
}
const validCards = [55707, 55705, 63163, 55773, 65209, 66727, 66793];
if (!validCards.includes(card_id)) {
  throw new Error('card_id ' + card_id + ' no autorizado. Válidos: ' + validCards.join(', '));
}
// UUIDs por card y slug
const PARAMS_MAP = {
  66727: {
    tipo_de_mercado: { id: 'fc0f2b30-20b6-4ab4-80c3-5f567a0d42ef', slug: 'tipo_de_mercado' },
    codigo_bia:      { id: 'e8cf66e8-028b-45ae-91e5-f2e52107266a', slug: 'codigo_bia' },
    tipo_de_medida:  { id: 'd1e69e96-72da-42d7-b296-8e110aedb448', slug: 'tipo_de_medida' },
    tipo_de_energia: { id: '11a33908-bb0e-4d1a-beb3-9dddb95c563e', slug: 'tipo_de_energia' }
  },
  66793: {
    codigo_bia:      { id: '1c43f3c9-7ce8-4341-9501-776bfce319f9', slug: 'codigo_bia' },
    tipo_de_medida:  { id: '6b92922c-9a4e-4ce3-aeca-8fc9c94cd977', slug: 'tipo_de_medida' },
    tipo_de_mercado: { id: '0c146346-59d0-4b91-9902-d2b3b55f0bdb', slug: 'tipo_de_mercado' }
  }
};
// Construir array de parameters solo con los filtros provistos
const parameters = [];
const cardParams = PARAMS_MAP[card_id] || {};
for (const key of Object.keys(cardParams)) {
  const val = raw[key];
  if (val && String(val).trim()) {
    parameters.push({
      id: cardParams[key].id,
      type: 'string/=',
      value: String(val).trim(),
      target: ['variable', ['template-tag', cardParams[key].slug]]
    });
  }
}
return [{ json: { card_id, parameters } }];

const resp = $input.first().json;
if (resp.error) return [{ json: { result: 'ERROR', error: resp.error, rows: [], count: 0 } }];
const cols = (resp.data?.cols || []).map(c => c.name);
const rows_raw = resp.data?.rows || [];
const rows = rows_raw.map(r => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
return [{ json: { result: 'OK', rows, count: rows.length } }];
